// File: MultiCatchParse.java
// Data shape: "id,date" -> Booking(int id, LocalDate date)
import java.time.LocalDate;
import java.time.format.DateTimeParseException;

public class MultiCatchParse {
    record Booking(int id, LocalDate date) {
    }

    static Booking parse(String line) {
        String[] parts = line.split(",", -1);
        if (parts.length != 2) {
            throw new IllegalArgumentException("expected id,date: " + line);
        }
        try {
            return new Booking(Integer.parseInt(parts[0].trim()), LocalDate.parse(parts[1].trim()));
        } catch (NumberFormatException | DateTimeParseException e) {
            // Both mean the same thing to the caller: the row is malformed.
            throw new IllegalArgumentException("bad row: " + line, e);
        }
    }

    public static void main(String[] args) {
        System.out.println(parse("7,2026-05-01"));
        try {
            parse("7,May 1");
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage() + " <- " + e.getCause().getClass().getSimpleName());
        }
    }
}

// File: CheckedVsUnchecked.java
// Data shape: readFirstLine(path) throws IOException; describe(id) throws nothing
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class CheckedVsUnchecked {

    // Checked: the file may be missing, and the caller can offer another path.
    static String readFirstLine(Path file) throws IOException {
        return Files.readAllLines(file).get(0);
    }

    // Unchecked: a negative id is a bug in the caller, not a runtime condition.
    static String describe(int hotelId) {
        if (hotelId < 1) {
            throw new IllegalArgumentException("hotel_id must be positive, got " + hotelId);
        }
        return "hotel " + hotelId;
    }

    public static void main(String[] args) {
        try {
            System.out.println(readFirstLine(Path.of("missing.csv")));
        } catch (IOException e) {
            // The compiler forced this catch, because the failure is expected.
            System.out.println("checked, handled here: " + e.getClass().getSimpleName());
        }

        System.out.println(describe(7));

        try {
            describe(-1);
        } catch (IllegalArgumentException e) {
            // Unchecked, so this catch is a choice, not an obligation.
            System.out.println("unchecked, caught by choice: " + e.getMessage());
        }
    }
}

// File: BookingException.java
// Data shape: BookingException { hotelId: int (0 = not hotel specific), cause: Throwable }
public class BookingException extends Exception {

    // 0 means the failure is not tied to one hotel, for example a whole file.
    private final int hotelId;

    public BookingException(String message) {
        super(message);
        this.hotelId = 0;
    }

    public BookingException(String message, Throwable cause) {
        super(message, cause);
        this.hotelId = 0;
    }

    public BookingException(int hotelId, String message, Throwable cause) {
        super("hotel " + hotelId + ": " + message, cause);
        this.hotelId = hotelId;
    }

    public int hotelId() {
        return hotelId;
    }

    public static void main(String[] args) {
        try {
            throw new BookingException(12, "guests exceed capacity", null);
        } catch (BookingException e) {
            // The handler reads the field, which is the reason the type exists.
            System.out.println(e.getMessage() + " (hotelId=" + e.hotelId() + ")");
        }
    }
}

// File: DuplicateHotelException.java
// Data shape: DuplicateHotelException { name: String }, unchecked
import java.util.HashSet;
import java.util.Set;

public class DuplicateHotelException extends RuntimeException {

    private final String name;

    public DuplicateHotelException(String name) {
        super("hotel already exists: " + name);
        this.name = name;
    }

    public DuplicateHotelException(String name, Throwable cause) {
        super("hotel already exists: " + name, cause);
        this.name = name;
    }

    public String name() {
        return name;
    }

    static void add(Set<String> names, String name) {
        if (!names.add(name)) {
            // Unchecked because the caller passed a duplicate, and no retry helps.
            throw new DuplicateHotelException(name);
        }
    }

    public static void main(String[] args) {
        Set<String> names = new HashSet<>();
        add(names, "Danube View");
        try {
            add(names, "Danube View");
        } catch (DuplicateHotelException e) {
            System.out.println(e.getMessage() + " -> " + e.name());
        }
    }
}

// File: WrapCause.java
// Data shape: StoreException(message, cause=SQLException) -> main reads getCause()
import java.sql.SQLException;

public class WrapCause {

    static class StoreException extends Exception {
        StoreException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    // Stands in for the driver: checked, low level, and full of vendor detail.
    static int countRows(String city) throws SQLException {
        if ("?".equals(city)) {
            throw new SQLException("syntax error at or near \"?\"", "42601");
        }
        return 3;
    }

    // Translation point: callers should not need java.sql on their import list.
    static int bookingsIn(String city) throws StoreException {
        try {
            return countRows(city);
        } catch (SQLException e) {
            // Pass e as the second argument. `e.getMessage()` here would lose the cause.
            throw new StoreException("cannot count bookings in " + city, e);
        }
    }

    public static void main(String[] args) {
        try {
            System.out.println(bookingsIn("?"));
        } catch (StoreException e) {
            System.out.println("domain: " + e.getMessage());
            System.out.println("cause: " + e.getCause());
            System.out.println("sql state: " + ((SQLException) e.getCause()).getSQLState());
        }
    }
}

// File: BatchFailures.java
// Data shape: BatchException { message, suppressed: Throwable[] } for a batch run
import java.util.List;

public class BatchFailures {

    static class BatchException extends RuntimeException {
        BatchException(String message) {
            super(message);
        }
    }

    static void process(String row) {
        if (row.startsWith("!")) {
            throw new IllegalArgumentException("cannot process " + row);
        }
        System.out.println("processed " + row);
    }

    // Runs every row, keeps the first failure primary, attaches the rest as suppressed.
    static void runAll(List<String> rows) {
        BatchException batch = null;

        for (String row : rows) {
            try {
                process(row);
            } catch (RuntimeException e) {
                if (batch == null) {
                    batch = new BatchException(rows.size() + " row batch failed");
                }
                batch.addSuppressed(e); // A list field would work too, but this stays throwable.
            }
        }

        if (batch != null) {
            throw batch;
        }
    }

    public static void main(String[] args) {
        try {
            runAll(List.of("row-1", "!row-2", "row-3", "!row-4"));
        } catch (BatchException e) {
            System.out.println(e.getMessage());
            for (Throwable failure : e.getSuppressed()) {
                System.out.println("  failed: " + failure.getMessage());
            }
        }
    }
}

// File: StackFrames.java
// Data shape: e.getStackTrace() -> StackTraceElement[] {className, methodName, fileName, lineNumber}
public class StackFrames {

    static void inner() {
        throw new IllegalStateException("parser gave up");
    }

    static void middle() {
        inner();
    }

    static void outer() {
        middle();
    }

    public static void main(String[] args) {
        try {
            outer();
        } catch (IllegalStateException e) {
            StackTraceElement[] frames = e.getStackTrace();

            System.out.println("depth: " + frames.length);
            // Frame 0 is the throw site, so it names the line that created the object.
            System.out.println("created at: " + frames[0]);
            System.out.println("its caller: " + frames[1]);

            for (int i = 0; i < Math.min(3, frames.length); i++) {
                StackTraceElement frame = frames[i];
                System.out.println("  #" + i + " " + frame.getMethodName()
                        + " line " + frame.getLineNumber() + " in " + frame.getFileName());
            }

            // Trimming for a log: keep only frames from the application's own classes.
            for (StackTraceElement frame : frames) {
                if (frame.getClassName().startsWith("StackFrames")) {
                    System.out.println("app: " + frame);
                }
            }
        }
    }
}

// File: ResourcesOrder.java
// Data shape: try (a; b; c) closes c, then b, then a, always
public class ResourcesOrder {

    static class Handle implements AutoCloseable {
        private final String name;

        Handle(String name) {
            this.name = name;
            System.out.println("open " + name);
        }

        void use() {
            System.out.println("use " + name);
        }

        @Override
        public void close() {
            // close() runs even when the body throws, so this line always prints.
            System.out.println("close " + name);
        }
    }

    public static void main(String[] args) {
        // Declare in acquisition order: connection, statement, result set.
        try (Handle connection = new Handle("connection");
             Handle statement = new Handle("statement");
             Handle resultSet = new Handle("result set")) {

            connection.use();
            statement.use();
            resultSet.use();
            // A throw here would still close resultSet, statement, connection.
        }

        // Java 9 form: an existing, effectively final variable can be listed alone.
        Handle late = new Handle("late handle");
        try (late) {
            late.use();
        }
    }
}

// File: UncaughtHandler.java
// Data shape: handler receives (thread: Thread, error: Throwable) for every uncaught failure
public class UncaughtHandler {

    public static void main(String[] args) throws InterruptedException {
        Thread.setDefaultUncaughtExceptionHandler((thread, error) -> {
            // Runs on the dying thread, so keep it short and never throw here.
            System.out.println("uncaught in " + thread.getName() + ": " + error);

            for (Throwable cause = error.getCause(); cause != null; cause = cause.getCause()) {
                System.out.println("  caused by " + cause);
            }
        });

        Thread worker = new Thread(() -> {
            throw new IllegalStateException("worker died",
                    new java.io.IOException("socket closed"));
        }, "import-worker");

        worker.start();
        worker.join(); // Wait, otherwise main may exit before the handler prints.

        System.out.println("main still alive");
    }
}

// File: LogOnce.java
// Data shape: one log record per failure, carrying message and throwable
import java.util.logging.Level;
import java.util.logging.Logger;

public class LogOnce {

    private static final Logger LOG = Logger.getLogger(LogOnce.class.getName());

    static class RepoException extends Exception {
        RepoException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    static String load(String key) throws RepoException {
        try {
            if (key.isEmpty()) {
                throw new IllegalArgumentException("empty key");
            }
            return "value for " + key;
        } catch (IllegalArgumentException e) {
            // Wrap with the cause and stay silent: the boundary owns the log line.
            throw new RepoException("cannot load '" + key + "'", e);
        }
    }

    public static void main(String[] args) {
        try {
            System.out.println(load(""));
        } catch (RepoException e) {
            // The throwable argument prints the whole stack, so no second log is needed.
            LOG.log(Level.SEVERE, e.getMessage(), e);
            System.out.println("load failed, see log");
        }
    }
}

// File: FinallyCleanup.java
// Data shape: try { return a; } catch { return b; } finally { cleanup }
public class FinallyCleanup {

    private static final StringBuilder LOG = new StringBuilder();

    static int parseOrZero(String text) {
        try {
            return Integer.parseInt(text);
        } catch (NumberFormatException e) {
            return 0;
        } finally {
            // Runs before either return reaches the caller, on both paths.
            LOG.append("parsed '").append(text).append("'; ");
        }
    }

    public static void main(String[] args) {
        System.out.println(parseOrZero("12"));
        System.out.println(parseOrZero("x"));
        System.out.println(LOG);

        // Do not return from finally: it discards the exception and the earlier value.
    }
}

// File: ValidateStars.java
// Data shape: validateStars(int) -> void, throws IllegalArgumentException on bad input
public class ValidateStars {

    static final int MIN = 1;
    static final int MAX = 5;

    static void validateStars(int stars) {
        // Fail fast, and put the field name and the received value in the message.
        if (stars < MIN || stars > MAX) {
            throw new IllegalArgumentException(
                    "stars must be " + MIN + ".." + MAX + ", got " + stars);
        }
    }

    // The caller validates once, then works with a value it can trust.
    static String label(int stars) {
        validateStars(stars);
        return switch (stars) {
            case 1, 2 -> "budget";
            case 3 -> "standard";
            default -> "premium";
        };
    }

    public static void main(String[] args) {
        System.out.println(label(4));

        try {
            System.out.println(label(9));
        } catch (IllegalArgumentException e) {
            // No throws clause was needed: validation failures are unchecked.
            System.out.println(e.getMessage());
        }
    }
}
